  const normalized = Number.isFinite(Number(seed)) ? Math.trunc(Number(seed)) : 18;
  state.seed = normalized;
  state.mode = "poster";
  state.motionTime = 0;
  state.playing = false;
  state.lastFrame = performance.now();
  state.instrument.pointerX = .66;
  state.instrument.pointerY = .52;
  state.instrument.targetX = .66;
  state.instrument.targetY = .52;
  state.instrument.down = false;
  state.instrument.energy = 0;
  state.instrument.dragCount = 0;
  state.instrument.pulse = 0;
  state.instrument.phase = 0;
  generateIdentity(normalized);
  updateModeUI();
  updateSeedUI();
  updateTransportUI();
  renderMotion();
  renderInstrument();
  return snapshot();
}

function setMode(name) {
  if (!MODES.includes(name)) return false;
  state.mode = name;
  if (name !== "motion") state.playing = false;
  state.lastFrame = performance.now();
  updateModeUI();
  updateTransportUI();
  if (name === "motion") renderMotion();
  if (name === "instrument") {
    renderInstrument();
    requestAnimationFrame(() => els.instrumentCanvas.focus({ preventScroll: true }));
  }
  return true;
}

function seek(milliseconds) {
  const next = Number(milliseconds);
  state.motionTime = Number.isFinite(next) ? clamp(next, 0, DURATION) : 0;
  if (state.motionTime >= DURATION) state.playing = false;
  state.lastFrame = performance.now();
  updateTransportUI();
  renderMotion();
  return state.motionTime;
}

function snapshot() {
  const inst = state.instrument;
  return {
    seed: state.seed,
    mode: state.mode,
    motionTime: Math.round(state.motionTime * 1000) / 1000,
    playing: state.playing,
    instrument: {
      pointer: [Number(inst.pointerX.toFixed(5)), Number(inst.pointerY.toFixed(5))],
      target: [Number(inst.targetX.toFixed(5)), Number(inst.targetY.toFixed(5))],
      energy: Number(inst.energy.toFixed(5)),
      dragCount: inst.dragCount,
      pulse: Number(inst.pulse.toFixed(5)),
      phase: Number(inst.phase.toFixed(5)),
      strandCount: inst.strands.length
    }
  };
}

function runSelfTest() {
  const tests = [];
  const add = (name, pass, detail) => tests.push({ name, pass: Boolean(pass), detail });
  const previous = snapshot();

  const first = reset(2468);
  setMode("instrument");
  applyInstrumentInput(.23, .71, true, .84);
  reset(2468);
  const second = snapshot();
  add("deterministic reset", JSON.stringify(first) === JSON.stringify(second), "Seed 2468 restores identical complete state.");

  const modeResults = MODES.map((mode) => setMode(mode) && state.mode === mode);
  add("all modes", modeResults.every(Boolean), "Poster, motion, and instrument accept programmatic entry.");

  setMode("motion");
  seek(4321);
  add("exact motion seek", state.motionTime === 4321, "Motion time is exactly 4321 ms.");

  seek(15000);
  const upper = state.motionTime === 12000;
  seek(-200);
  const lower = state.motionTime === 0;
  add("timeline boundary", upper && lower, "Timeline clamps to the inclusive 0 through 12000 ms range.");

  setMode("instrument");
  applyInstrumentInput(.81, .17, true, 1.25);
  stepInstrument(.016);
  const numeric = [state.instrument.pointerX, state.instrument.pointerY, state.instrument.energy, state.instrument.pulse, state.instrument.phase];
  add("finite interaction state", numeric.every(Number.isFinite), "Pointer, energy, pulse, and phase remain finite after real interaction updates.");

  reset(previous.seed);
  setMode(previous.mode);
  seek(previous.motionTime);
  state.playing = previous.playing && previous.motionTime < DURATION;
  Object.assign(state.instrument, {
    pointerX: previous.instrument.pointer[0],
    pointerY: previous.instrument.pointer[1],
    targetX: previous.instrument.target[0],
    targetY: previous.instrument.target[1],
    energy: previous.instrument.energy,
    dragCount: previous.instrument.dragCount,
    pulse: previous.instrument.pulse,
    phase: previous.instrument.phase
  });
  updateTransportUI();
  return { passed: tests.every((test) => test.pass), tests };
}

function updateModeUI() {
  els.modes.forEach((mode) => {
    const active = mode.id === state.mode;
    mode.classList.toggle("is-active", active);
    mode.setAttribute("aria-hidden", String(!active));
  });
  els.modeButtons.forEach((button) => {
    const active = button.dataset.mode === state.mode;
    button.setAttribute("aria-selected", String(active));
    button.tabIndex = active ? 0 : -1;
  });
}

function updateSeedUI() {
  els.seedButtons.forEach((button) => button.setAttribute("aria-pressed", String(Number(button.dataset.seed) === state.seed)));
}

function formatTime(milliseconds) {
  const safe = clamp(Math.round(milliseconds), 0, DURATION);
  const seconds = Math.floor(safe / 1000);
  const millis = safe % 1000;
  return `00:${String(seconds).padStart(2, "0")}.${String(millis).padStart(3, "0")}`;
}

function updateTransportUI() {
  els.timeline.value = String(Math.round(state.motionTime));
  els.timecode.value = `${formatTime(state.motionTime)} / 00:12.000`;
  els.timecode.textContent = els.timecode.value;
  els.playPause.textContent = state.playing ? "Pause" : "Play";
  els.playPause.setAttribute("aria-label", state.playing ? "Pause motion sequence" : "Play motion sequence");
}

