  await shot("08-seed-1930", "window.__LIVING_IDENTITY__.reset(1930);");

  const cons = await cdp(ws, "Runtime.evaluate", {
    expression: "JSON.stringify({title:document.title,h1:document.querySelector('h1').textContent,errors:window.__errs||[]})",
    returnByValue: true
  }, sessionId);
