  console.log("logs", JSON.stringify(logs, null, 2));
  ws.close();
} catch (err) {
  console.error("FAIL", err);
  process.exitCode = 1;
} finally {
  proc.kill("SIGTERM");
  setTimeout(() => proc.kill("SIGKILL"), 500);
}
