function drawSlit(ctx, ox, oy, angle, length, width, intensity, pal, chromatic) {
  ctx.save();
  ctx.translate(ox, oy);
  ctx.rotate(angle);
  const hw = width / 2;
  const hl = length / 2;
  if (chromatic) {
    ctx.globalCompositeOperation = "lighter";
    ctx.fillStyle = pal.flare;
    ctx.globalAlpha = intensity * 0.45;
    ctx.fillRect(-hl, -hw - 1.2, length, width);
    ctx.fillStyle = pal.oxide;
    ctx.globalAlpha = intensity * 0.35;
    ctx.fillRect(-hl, -hw + 1.2, length, width);
  }
  ctx.globalCompositeOperation = "source-over";
  ctx.fillStyle = pal.corona;
  ctx.globalAlpha = intensity;
  ctx.fillRect(-hl, -hw, length, width);
  ctx.globalAlpha = intensity * 0.22;
  ctx.fillRect(-hl, -hw - 6, length, 1.2);
  ctx.fillRect(-hl, hw + 5, length, 1.2);
  ctx.globalAlpha = intensity * 0.12;
  ctx.fillRect(-hl, -hw - 11, length, 1);
  ctx.fillRect(-hl, hw + 10, length, 1);
  ctx.restore();
}

function drawSlit(ctx, ox, oy, angle, length, width, intensity, pal, chromatic) {
  ctx.save();
  ctx.translate(ox, oy);
  ctx.rotate(angle);
  const hw = width / 2;
  const hl = length / 2;
  if (chromatic) {
    ctx.globalCompositeOperation = "lighter";
    ctx.fillStyle = pal.flare;
    ctx.globalAlpha = intensity * 0.45;
    ctx.fillRect(-hl, -hw - 1.2, length, width);
    ctx.fillStyle = pal.oxide;
    ctx.globalAlpha = intensity * 0.35;
    ctx.fillRect(-hl, -hw + 1.2, length, width);
  }
  ctx.globalCompositeOperation = "source-over";
  ctx.fillStyle = pal.corona;
  ctx.globalAlpha = intensity;
  ctx.fillRect(-hl, -hw, length, width);
  ctx.globalAlpha = intensity * 0.22;
  ctx.fillRect(-hl, -hw - 6, length, 1.2);
  ctx.fillRect(-hl, hw + 5, length, 1.2);
  ctx.globalAlpha = intensity * 0.12;
  ctx.fillRect(-hl, -hw - 11, length, 1);
  ctx.fillRect(-hl, hw + 10, length, 1);
  ctx.restore();
}

