function drawCutGlyph(ctx, ch, x, y, pal, ox, oy, angle, cut, alpha) {
  if (alpha <= 0.01) return;
  const span = 5000;
  ctx.save();
  ctx.globalAlpha = alpha;
  ctx.fillStyle = pal.bone;
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.save();
  clipHalf(ctx, ox, oy, angle, -1, span);
  ctx.fillText(ch, x - cut, y);
  ctx.restore();
  ctx.save();
  clipHalf(ctx, ox, oy, angle, 1, span);
  ctx.fillText(ch, x + cut, y);
  ctx.restore();
  ctx.restore();
}

function drawCutWord(ctx, text, x, y, font, pal, ox, oy, angle, cut, tracking, alphas) {
  ctx.save();
  ctx.font = font;
  ctx.textBaseline = "middle";
  ctx.textAlign = "left";
  const letters = Array.from(text);
  const widths = letters.map((ch) => ctx.measureText(ch).width);
  const extra = (ctx.measureText("M").width) * tracking;
  const total = widths.reduce((a, b) => a + b, 0) + extra * (letters.length - 1);
  let px = x - total / 2;
  letters.forEach((ch, i) => {
    const w = widths[i];
    const a = Array.isArray(alphas) ? alphas[i] : alphas;
    ctx.save();
    ctx.textAlign = "left";
    drawCutGlyph(ctx, ch, px + w / 2, y, pal, ox, oy, angle, cut, a);
    ctx.restore();
    px += w + extra;
  });
  ctx.restore();
}

