function renderPoster() {
  const { w, h } = fitCanvas(els.poster, posterCtx);
  if (w < 2 || h < 2) return;
  const ctx = posterCtx;
  const id = state.identity;
  const pal = colors(id);
  const display = getComputedStyle(document.body).getPropertyValue("--display");
  const plate = getComputedStyle(document.body).getPropertyValue("--plate");
  const mono = getComputedStyle(document.body).getPropertyValue("--mono");
  ctx.clearRect(0, 0, w, h);
  ctx.fillStyle = pal.night;
  ctx.fillRect(0, 0, w, h);

  const letters = Array.from(EVENT.name);
  const nameSize = Math.round(h * 0.074);
  const stackGap = nameSize * 1.06;
  const stackTop = h * 0.168;
  const oIndex = letters.indexOf("O");
  const cx = w * id.slitX;
  const cy = stackTop + oIndex * stackGap;
  const maxR = h * 0.58;
  const slitAngle = Math.PI / 2 + id.slitAngle;
  const cut = id.cut * (w / 380);

  ctx.save();
  ctx.fillStyle = pal.velvet;
  ctx.globalAlpha = 0.55;
  ctx.beginPath();
  ctx.arc(cx, cy, maxR * 0.155, 0, Math.PI * 2);
  ctx.fill();
  ctx.fillStyle = pal.night;
  ctx.globalAlpha = 1;
  ctx.beginPath();
  ctx.arc(cx, cy, maxR * 0.092, 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();

  drawRings(ctx, cx, cy, maxR, id, pal, 1, 0, 0.12);
  drawTicks(ctx, cx, cy, maxR * 0.88, id, pal, 0.3);

  ctx.save();
  ctx.strokeStyle = pal.flare;
  ctx.globalAlpha = 0.55;
  ctx.lineWidth = 1.2;
  const doorAng = id.markPhase + (19.5 / 24) * Math.PI * 2;
  ctx.beginPath();
  ctx.moveTo(cx + Math.cos(doorAng) * maxR * 0.2, cy + Math.sin(doorAng) * maxR * 0.2);
  ctx.lineTo(cx + Math.cos(doorAng) * maxR * 0.86, cy + Math.sin(doorAng) * maxR * 0.86);
  ctx.stroke();
  ctx.restore();

  const slitLen = h * 0.92;
  const slitWid = Math.max(2.2, w * 0.009);
  drawSlit(ctx, cx, cy, slitAngle, slitLen, slitWid, 0.95, pal, true);

  ctx.save();
  ctx.fillStyle = pal.corona;
  ctx.beginPath();
  ctx.arc(cx, cy, Math.max(2.2, w * 0.007), 0, Math.PI * 2);
  ctx.fill();
  ctx.restore();

  ctx.font = nameSize + "px " + display;
  letters.forEach((ch, i) => {
    const y = stackTop + i * stackGap;
    if (ch === "O") return;
    drawCutGlyph(ctx, ch, cx, y, pal, cx, cy, slitAngle, cut, 1);
  });

  ctx.save();
  ctx.fillStyle = pal.bone;
  ctx.globalAlpha = 0.12;
  ctx.font = Math.round(h * 0.2) + "px " + display;
  ctx.textAlign = "right";
  ctx.textBaseline = "middle";
  ctx.fillText("18", w * 0.9, h * 0.84);
  ctx.restore();

  ctx.save();
  ctx.fillStyle = pal.corona;
  ctx.font = "italic " + Math.round(w * 0.036) + "px " + display;
  ctx.textAlign = "left";
  ctx.textBaseline = "middle";
  const copyX = Math.min(w * 0.52, cx + w * 0.16);
  ctx.fillText("Festival of", copyX, h * 0.72);
  ctx.fillText("Impossible Light", copyX, h * 0.755);
  ctx.fillStyle = pal.bone;
  ctx.font = Math.round(w * 0.028) + "px " + plate;
  ctx.letterSpacing = "0.22em";
  ctx.fillText(EVENT.venue.toUpperCase(), copyX, h * 0.81);
  ctx.letterSpacing = "0";
  ctx.font = Math.round(w * 0.026) + "px " + display;
  ctx.fillText(EVENT.artists, copyX, h * 0.86);
  ctx.fillStyle = pal.flare;
  ctx.font = Math.round(w * 0.02) + "px " + plate;
  ctx.letterSpacing = "0.16em";
  ctx.fillText(EVENT.tension.toUpperCase(), copyX, h * 0.905);
  ctx.restore();

  drawPlateHeader(ctx, w, h * 0.055, pal, 1);

  ctx.save();
  ctx.translate(w * 0.042, h * 0.5);
  ctx.rotate(-Math.PI / 2);
  ctx.fillStyle = pal.oxide;
  ctx.font = "10px " + mono;
  ctx.letterSpacing = "0.32em";
  ctx.textAlign = "center";
  ctx.fillText("PLATE " + id.seed + "  ·  DOME SLIT", 0, 0);
  ctx.restore();

  ctx.save();
  ctx.strokeStyle = pal.corona;
  ctx.globalAlpha = 0.35;
  ctx.lineWidth = 1;
  ctx.strokeRect(w * 0.032, h * 0.026, w * 0.936, h * 0.948);
  ctx.restore();

  drawGrain(ctx, w, h, id);
}

