function motionScene(t) {
  const id = state.identity;
  const point = 0.18 + 0.82 * easeOutExpo(map(t, 60, 900));
  const slitGrow = easeOutCubic(map(t, 700, 2400));
  const rings = id.rings.map((_, i) => easeOutCubic(map(t, 1600 + i * 420, 2500 + i * 420)));
  const letters = Array.from(EVENT.name).map((_, i) => easeOutCubic(map(t, 5200 + i * 180, 6000 + i * 180)));
  const rot = reducedMotion ? 0 : lerp(0, 0.62, easeInOut(map(t, 1800, 7000)));
  const climax = Math.sin(map(t, 7400, 9100) * Math.PI);
  const closeGap = easeInOut(map(t, 7200, 8400)) * (1 - easeInOut(map(t, 9000, 10300)));
  const subtitle = easeOutCubic(map(t, 9000, 10200));
  const meta = easeOutCubic(map(t, 9800, 11300));
  const slitWidth = lerp(0.0035, 0.01, slitGrow) + climax * 0.05;
  const cut = lerp(id.cut * 3.4, id.cut * 0.15, easeOutCubic(map(t, 5200, 7400)));
  return {
    point, slitGrow, rings, letters, rot, climax, closeGap, subtitle, meta, slitWidth, cut,
    hold: map(t, 11300, 12000)
  };
}

